import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"macOS","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"macOS | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/macos"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/macos"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/macos"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/macos"}]]},"headers":[],"relativePath":"xclang/design/macos.md","filePath":"en/xclang/design/macos.md","lastUpdated":1791266105000}'),n={name:"xclang/design/macos.md"};function i(d,e,r,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h1><p>The macOS targets, <code>aarch64-apple-darwin</code> and <code>x86_64-apple-darwin</code>, build against Apple&#39;s SDK, with xclang&#39;s own libc++ linked in, and link with ld64.lld.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Apple&#39;s SDK cannot be redistributed. On a macOS host it comes from Xcode. On Linux and Windows hosts the user fetches it from Apple with the <code>xclang</code> command, and the toolchain&#39;s config files use it from there; that is <a href="./roadmap#macos-any-host">unreleased</a>. Programs carry their own libc++ and run on macOS 13 or later. ld64.lld links them on every host, which took a patch to lld.</p><h2 id="the-sdk-is-xcode-s" tabindex="-1">The SDK Is Xcode&#39;s <a class="header-anchor" href="#the-sdk-is-xcode-s" aria-label="Permalink to &quot;The SDK Is Xcode&#39;s&quot;">​</a></h2><p>Apple&#39;s SDK holds the headers and <code>.tbd</code> stubs of libSystem and the frameworks. No xclang archive has it, because it cannot be redistributed. On a macOS host, clang finds it the usual way: the last <code>-isysroot</code>, else <code>SDKROOT</code>, else the SDK of Xcode or the Command Line Tools (xcselect, as <code>xcrun</code> finds it).</p><p>When Xcode 27 shipped the macOS 27 SDK, its <code>.tbd</code> stubs listed a new architecture, <code>arm64e.x1</code>, that the TextAPI of LLVM 23.1.2 did not know. ld64.lld rejected the stubs of libSystem and every framework, and no program linked against the newest SDK. xclang carries LLVM&#39;s fix, which release/23.x backported for 23.1.3, as <a href="./../reference/patches">patch 0009</a> from 23.1.2.6 on.</p><h2 id="the-sdk-on-linux-and-windows-hosts" tabindex="-1">The SDK on Linux and Windows Hosts <a class="header-anchor" href="#the-sdk-on-linux-and-windows-hosts" aria-label="Permalink to &quot;The SDK on Linux and Windows Hosts&quot;">​</a></h2><p>On <code>main</code>, and in no release, the macOS targets build from Linux and Windows hosts too (<a href="./roadmap#macos-any-host">unreleased</a>). The SDK is the one the user fetches from Apple, accepting Apple&#39;s license (<a href="./vendor-sdks">vendor SDKs</a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=arm64-apple-macos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++23</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span></code></pre></div><p>The fetch unpacks the SDK into the toolchain&#39;s <code>sdk/macos-&lt;version&gt;</code> and points <code>sdk/macos</code> at it (<a href="./../reference/xclang-command#the-sdk-in-use">the SDK in use</a>). On those hosts the config files of the macOS targets begin with <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>, so a bare <code>--target</code> finds it. Which SDK a compile uses:</p><table tabindex="0"><thead><tr><th>host</th><th>the SDK</th></tr></thead><tbody><tr><td>macOS</td><td>the last <code>-isysroot</code>, else <code>SDKROOT</code>, else Xcode&#39;s (xcselect)</td></tr><tr><td>Linux, Windows</td><td>the last <code>-isysroot</code> of the command line, else <code>sdk/macos</code></td></tr></tbody></table><p>On Linux and Windows clang does not read <code>SDKROOT</code>: it does so only when there is no <code>-isysroot</code>, and the config file has one. Build systems that honor <code>SDKROOT</code> pass it as <code>-isysroot</code>, which wins: cargo and rustc, and the CMake package (<a href="./../integrations/cmake#build-for-macos-from-linux-or-windows">CMake</a>). Without the SDK, clang warns that <code>sdk/macos</code> does not exist and finds no C header.</p><p>Why a fixed path in the config file, and not a config file that the fetch writes, as the MSVC targets have (<a href="./windows#msvc-targets">Windows</a>): a macOS SDK needs no versions or options besides its path, and an <code>-isysroot</code> of the command line still works when no SDK is fetched into the toolchain.</p><p>The programs are those of a macOS host: the same libc++, linker, dSYMs, universal programs and sanitizers. ld64.lld signs arm64 programs ad hoc, as Apple&#39;s <code>ld</code> does, so they run on Apple silicon without <code>codesign</code>; <code>llvm-install-name-tool</code> signs them again when it changes them. CI builds them on Linux and Windows hosts, x64 and arm64, and runs them on arm64 and x64 Macs (<a href="./../dev/testing#macos-from-linux-and-windows">testing</a>).</p><h2 id="xclang-s-libc-not-the-system-s" tabindex="-1">xclang&#39;s libc++, Not the System&#39;s <a class="header-anchor" href="#xclang-s-libc-not-the-system-s" aria-label="Permalink to &quot;xclang&#39;s libc++, Not the System&#39;s&quot;">​</a></h2><p>The config file puts xclang&#39;s libc++ headers on the C++ include path and its <code>libc++.a</code> ahead of the SDK&#39;s <code>libc++.tbd</code>. So programs link libc++ and libc++abi statically, as on the other targets. The unwinder is the system&#39;s, in libSystem.</p><ul><li>The system&#39;s <code>libc++.dylib</code> is the libc++ of the OS version, not the one the headers came from. Apple marks newer library features as needing a newer macOS. With the library inside the program, its features depend on the xclang release, not on the macOS version the program runs on.</li><li>Every target has the same libc++, so the C++ of a program behaves the same on macOS, Linux and Windows.</li></ul><p>Programs run on macOS 13.0 and later. The config file passes <code>-mmacos-version-min=13.0</code>; a later one on the command line replaces it.</p><h2 id="ld64-lld" tabindex="-1">ld64.lld <a class="header-anchor" href="#ld64-lld" aria-label="Permalink to &quot;ld64.lld&quot;">​</a></h2><p>macOS targets link with ld64.lld, on macOS hosts too. <code>-fuse-ld=ld</code> selects Apple&#39;s <code>ld</code> instead, with xclang&#39;s <code>lib/libLTO.dylib</code> for LTO.</p><p>Why the LLVM linker and not Apple&#39;s:</p><ul><li><strong>The same linker on every host.</strong> A macOS target built from Linux or Windows needs ld64.lld. Using it on macOS too means one linker to test.</li><li><strong>LTO with the same LLVM.</strong> Apple&#39;s <code>ld</code> does LTO through a <code>libLTO.dylib</code>, which must match the LLVM version of the compiler. It loads one given by <code>-lto_library</code> only by an absolute path, and under Bazel that took a wrapper script. ld64.lld is the LLVM it was built with.</li><li><strong>The same flags in every build</strong> for the ThinLTO cache (<code>-cache_path_lto</code>) and relative debug maps (<code>-oso_prefix</code>).</li></ul><h3 id="the-patch-it-took" tabindex="-1">The Patch It Took <a class="header-anchor" href="#the-patch-it-took" aria-label="Permalink to &quot;The Patch It Took&quot;">​</a></h3><p>In the tests of the first release, a program compiled and linked by one clang command with ThinLTO terminated on arm64 instead of catching its own exception. LLVM&#39;s own ld64.lld did the same. xclang switched macOS targets to Apple&#39;s <code>ld</code> for the next releases while the cause was found.</p><p>When clang compiles and links in one command, it passes <code>-object_path_lto</code>. With it, the LTO backend writes an empty object first, and that object&#39;s only symbol, <code>ltmp0</code>, has the address of what follows it: <code>main</code>. ld64.lld collected unwind entries from every symbol in code, so the empty entry of <code>ltmp0</code> took the place of <code>main</code> in <code>__unwind_info</code>. Then <code>main</code> could not be unwound through. Two diagnostic runs, with and without upstream&#39;s fix (llvm/llvm-project#225055), confirmed it was exactly that.</p><p><a href="./../reference/patches">Patch 0007</a> carries the fix. From 23.1.2.5 on, the macOS targets link with ld64.lld everywhere, and from 23.1.2.6 on xclang&#39;s own macOS builds do too.</p><h2 id="debug-information" tabindex="-1">Debug Information <a class="header-anchor" href="#debug-information" aria-label="Permalink to &quot;Debug Information&quot;">​</a></h2><p>A macOS program keeps its DWARF in the object files, which its debug map names by path, and dsymutil collects it into a dSYM. Two things follow, both handled in the build integrations:</p><ul><li><strong>The paths.</strong> The debug map names each object by its absolute path, so the same program linked in two directories differs. Bazel links pass <code>-oso_prefix .</code>, and the map names <code>bazel-out/...</code>.</li><li><strong>ThinLTO&#39;s objects.</strong> With ThinLTO, the code is in the objects of the LTO backend, which the linker deletes. So xclang makes the dSYM in the link (<a href="./../features/debugging#why-a-dsym-comes-from-the-link">why a dSYM comes from the link</a>).</li></ul><p>A shipped program is stripped with <code>--strip-all</code>, as Apple&#39;s <code>strip</code> does (<a href="./../features/debugging#strip">strip</a>).</p><h2 id="two-architectures" tabindex="-1">Two Architectures <a class="header-anchor" href="#two-architectures" aria-label="Permalink to &quot;Two Architectures&quot;">​</a></h2><p>The arm64 and x86_64 targets are both in every archive. To CMake, the other macOS architecture is <code>CMAKE_OSX_ARCHITECTURES</code>, not cross-compiling. x86_64 programs run on arm64 Macs through Rosetta, but not the reverse. The x86_64 macOS toolchain itself is cross-compiled on arm64 macOS.</p><h2 id="sanitizers" tabindex="-1">Sanitizers <a class="header-anchor" href="#sanitizers" aria-label="Permalink to &quot;Sanitizers&quot;">​</a></h2><p>ASan, TSan, LSan, UBSan and libFuzzer work as on Linux, and so does the ASan libc++. Their runtimes are dylibs on macOS, loaded from the toolchain or from the directory of the program. That is the one exception to <a href="./hermeticity#known-limitations">hermeticity</a>, for test builds.</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./roadmap#macos-any-host">macOS targets from Linux and Windows hosts</a></td><td><span class="status-badge warn">Unreleased</span></td></tr><tr><td><a href="./roadmap#macos-any-host-bazel">macOS targets from Linux and Windows hosts in the Bazel module</a></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a href="./roadmap#ios">iOS, tvOS, watchOS, visionOS and their simulators</a></td><td><span class="status-badge note">In research</span></td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>No app bundles&#39; resources off macOS.</strong> Asset catalogs and nibs need Apple&#39;s <code>actool</code> and <code>ibtool</code>, which run only on macOS. Command-line programs, dylibs and frameworks of code build on every host.</li><li><strong>No notarization.</strong> Programs are signed ad hoc by the linker. Signing with a Developer ID and notarizing need Apple&#39;s tools and an Apple account.</li><li><strong>Apple&#39;s license.</strong> The SDK is used under Apple&#39;s terms, which the user accepts when fetching it (<a href="./vendor-sdks">vendor SDKs</a>).</li></ul>`,39)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
